/*---
description: NFKC agrees with Node for every code point U+000000 through U+00FFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [890621391, 3005523314, 732753796, 709516738, 3680693701, 2194763205, 2892066245, 1899982277, 362769861, 2643684805, 2169705129, 1260613061, 3317034437, 3690163653, 1459252677, 2967703979];
const blocks = ["NFKC U+000000-U+000FFF", "NFKC U+001000-U+001FFF", "NFKC U+002000-U+002FFF", "NFKC U+003000-U+003FFF", "NFKC U+004000-U+004FFF", "NFKC U+005000-U+005FFF", "NFKC U+006000-U+006FFF", "NFKC U+007000-U+007FFF", "NFKC U+008000-U+008FFF", "NFKC U+009000-U+009FFF", "NFKC U+00A000-U+00AFFF", "NFKC U+00B000-U+00BFFF", "NFKC U+00C000-U+00CFFF", "NFKC U+00D000-U+00DFFF", "NFKC U+00E000-U+00EFFF", "NFKC U+00F000-U+00FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 0 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFKC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
